ALTER TABLE devices ALTER COLUMN category_id SET NOT NULL, ADD CONSTRAINT devices_status_check CHECK (status IN ('IN_USE','IDLE','SOLD','DISCARDED')), ADD CONSTRAINT devices_purchase_price_check CHECK (purchase_price_cents IS NULL OR purchase_price_cents >= 0), ADD CONSTRAINT devices_disposal_price_check CHECK (disposal_price_cents IS NULL OR disposal_price_cents >= 0), ADD CONSTRAINT devices_disposal_date_check CHECK (disposal_date IS NULL OR purchase_date IS NULL OR disposal_date >= purchase_date), ADD CONSTRAINT devices_currency_mvp_check CHECK (currency = 'CNY'), ADD CONSTRAINT devices_id_user_key UNIQUE (id, user_id);
